mapper.select:
SELECT
FROM registration r LEFT JOIN patient p ON p.id = r.patient_id LEFT JOIN doctor d ON d.id = r.doctor_id LEFT JOIN department dept ON dept.id = r.department_id LEFT JOIN schedule s ON s.id = r.schedule_id
AND r.user_id = #{userId}
AND r.status IN
#{status}
AND r.work_date = #{date}
AND (p.name LIKE CONCAT('%', #{keyword}, '%') OR d.name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY r.work_date DESC, r.id DESC
